+use std::io::ErrorKind;
+use std::path::{Path, PathBuf};
+
+use callisto_model::ManifestFormat;
+use globset::{GlobBuilder, GlobSet, GlobSetBuilder};
+
+use crate::locate::LocateError;
+
+/// The only two valid authority states. Invalid authority is always an error.
+pub(crate) enum MembershipAuthority<T> {
+    Absent,
+    Present(T),
+}
+
+pub(crate) struct NegatableGlobSet {
+    positive: GlobSet,
+    negative: GlobSet,
+}
+
+impl NegatableGlobSet {
+    pub(crate) fn is_match(&self, path: &Path) -> bool {
+        self.positive.is_match(path) && !self.negative.is_match(path)
+    }
+
+    fn empty() -> Self {
+        Self {
+            positive: GlobSet::empty(),
+            negative: GlobSet::empty(),
+        }
+    }
+}
+
+#[derive(Clone, Copy)]
+struct AuthorityPath {
+    ecosystem: &'static str,
+    path: &'static str,
+}
+
+impl AuthorityPath {
+    fn relative_path(self) -> PathBuf {
+        PathBuf::from(self.path)
+    }
+
+    fn field_error(self, field: &'static str, detail: &'static str) -> LocateError {
+        LocateError::MembershipField {
+            ecosystem: self.ecosystem,
+            path: self.relative_path(),
+            field,
+            detail,
+        }
+    }
+}
+
+fn read_authority(root: &Path, authority: AuthorityPath) -> Result<Option<String>, LocateError> {
+    let path = root.join(authority.path);
+    match std::fs::read_to_string(&path) {
+        Ok(content) => Ok(Some(content)),
+        Err(error) if error.kind() == ErrorKind::NotFound => Ok(None),
+        Err(error) => Err(LocateError::MembershipRead {
+            ecosystem: authority.ecosystem,
+            path: authority.relative_path(),
+            message: error.to_string(),
+        }),
+    }
+}
+
+fn build_globset(
+    entries: &[String],
+    authority: AuthorityPath,
+    field: &'static str,
+) -> Result<NegatableGlobSet, LocateError> {
+    let mut positive = GlobSetBuilder::new();
+    let mut negative = GlobSetBuilder::new();
+    for entry in entries {
+        let (builder, pattern) = match entry.strip_prefix('!') {
+            Some(rest) => (&mut negative, rest),
+            None => (&mut positive, entry.as_str()),
+        };
+        let glob = GlobBuilder::new(pattern)
+            .literal_separator(true)
+            .build()
+            .map_err(|error| LocateError::MembershipGlob {
+                ecosystem: authority.ecosystem,
+                path: authority.relative_path(),
+                field,
+                pattern: entry.clone(),
+                message: error.to_string(),
+            })?;
+        builder.add(glob);
+    }
+    let positive = positive.build().map_err(|error| LocateError::MembershipGlob {
+        ecosystem: authority.ecosystem,
+        path: authority.relative_path(),
+        field,
+        pattern: "<compiled positive set>".to_string(),
+        message: error.to_string(),
+    })?;
+    let negative = negative.build().map_err(|error| LocateError::MembershipGlob {
+        ecosystem: authority.ecosystem,
+        path: authority.relative_path(),
+        field,
+        pattern: "<compiled negative set>".to_string(),
+        message: error.to_string(),
+    })?;
+    Ok(NegatableGlobSet { positive, negative })
+}
+
+pub(crate) struct Membership {
+    members: Option<NegatableGlobSet>,
+    exclude: NegatableGlobSet,
+    hybrid_root: bool,
+}
+
+impl Membership {
+    pub(crate) fn admits(&self, rel: &Path, is_root: bool) -> bool {
+        if is_root && self.hybrid_root {
+            return true;
+        }
+        !self.exclude.is_match(rel) && self.members.as_ref().is_none_or(|members| members.is_match(rel))
+    }
+}
