+    manifest_file_name: ManifestFormat::CargoToml.file_name(),
+    table_path: &["workspace"],
+    owner_key: "package",
+    ecosystem: "Cargo",
+};
+
+pub(crate) const PYTHON_MEMBERSHIP_SPEC: MembershipSpec = MembershipSpec {
+    manifest_file_name: ManifestFormat::PyprojectToml.file_name(),
+    table_path: &["tool", "uv", "workspace"],
+    owner_key: "project",
+    ecosystem: "uv",
+};
+
+fn membership_authority(spec: &MembershipSpec) -> AuthorityPath {
+    AuthorityPath {
+        ecosystem: spec.ecosystem,
+        path: spec.manifest_file_name,
+    }
+}
+
+fn table_at<'a>(
+    doc: &'a toml_edit::DocumentMut,
+    spec: &MembershipSpec,
+    authority: AuthorityPath,
+) -> Result<Option<&'a toml_edit::Item>, LocateError> {
+    let mut item = match doc.get(spec.table_path[0]) {
+        Some(item) => item,
+        None => return Ok(None),
+    };
+    for key in spec.table_path.iter().skip(1) {
+        item = item.get(*key).ok_or_else(|| {
+            authority.field_error("workspace", "must be a table containing the workspace authority")
+        })?;
+    }
+    if item.as_table().is_none() {
+        return Err(authority.field_error("workspace", "must be a workspace table"));
+    }
+    Ok(Some(item))
+}
+
+fn parse_toml_string_array(
+    item: &toml_edit::Item,
+    authority: AuthorityPath,
+    field: &'static str,
+) -> Result<Vec<String>, LocateError> {
+    let array = item
+        .as_array()
+        .ok_or_else(|| authority.field_error(field, "must be an array of strings"))?;
+    array
+        .iter()
+        .map(|value| {
+            value
+                .as_str()
+                .map(ToOwned::to_owned)
+                .ok_or_else(|| authority.field_error(field, "must contain only strings"))
+        })
+        .collect()
+}
+
+pub(crate) fn read_membership(
+    root: &Path,
+    spec: &MembershipSpec,
+) -> Result<MembershipAuthority<Membership>, LocateError> {
+    let authority = membership_authority(spec);
+    let Some(content) = read_authority(root, authority)? else {
+        return Ok(MembershipAuthority::Absent);
+    };
+    let doc = content
+        .parse::<toml_edit::DocumentMut>()
+        .map_err(|error| LocateError::MembershipParse {
+            ecosystem: authority.ecosystem,
+            path: authority.relative_path(),
+            parser: "TOML",
+            message: error.to_string(),
+        })?;
+    let Some(workspace) = table_at(&doc, spec, authority)? else {
+        return Ok(MembershipAuthority::Absent);
+    };
+    let members = workspace
+        .get("members")
+        .map(|item| parse_toml_string_array(item, authority, "members"))
+        .transpose()?
+        .map(|entries| build_globset(&entries, authority, "members"))
+        .transpose()?;
+    let exclude = workspace
+        .get("exclude")
+        .map(|item| parse_toml_string_array(item, authority, "exclude"))
+        .transpose()?
+        .map(|entries| build_globset(&entries, authority, "exclude"))
+        .transpose()?
+        .unwrap_or_else(NegatableGlobSet::empty);
+    Ok(MembershipAuthority::Present(Membership {
+        members,
+        exclude,
+        hybrid_root: doc.get(spec.owner_key).is_some(),
+    }))
+}
+
+pub(crate) fn read_cargo_membership(root: &Path) -> Result<MembershipAuthority<Membership>, LocateError> {
+    read_membership(root, &CARGO_MEMBERSHIP_SPEC)
+}
+
+pub(crate) fn read_python_membership(root: &Path) -> Result<MembershipAuthority<Membership>, LocateError> {
+    read_membership(root, &PYTHON_MEMBERSHIP_SPEC)
+}
+
+pub(crate) struct NpmMembership {
+    globs: NegatableGlobSet,
+    hybrid_root: bool,
+}
+
+impl NpmMembership {
+    pub(crate) fn admits(&self, rel: &Path, is_root: bool) -> bool {
+        (is_root && self.hybrid_root) || self.globs.is_match(rel)
+    }
+}
+
+const PACKAGE_JSON_AUTHORITY: AuthorityPath = AuthorityPath {
+    ecosystem: "npm",
+    path: "package.json",
+};
+const PNPM_AUTHORITY: AuthorityPath = AuthorityPath {
+    ecosystem: "pnpm",
+    path: "pnpm-workspace.yaml",
+};
+
+struct PackageJsonMembership {
+    packages: Option<Vec<String>>,
+    hybrid_root: bool,
+}
+
+fn read_package_json_membership(
+    root: &Path,
+) -> Result<MembershipAuthority<PackageJsonMembership>, LocateError> {
+    let Some(content) = read_authority(root, PACKAGE_JSON_AUTHORITY)? else {
+        return Ok(MembershipAuthority::Absent);
+    };
+    let value = serde_json::from_str::<serde_json::Value>(&content).map_err(|error| {
+        LocateError::MembershipParse {
+            ecosystem: PACKAGE_JSON_AUTHORITY.ecosystem,
+            path: PACKAGE_JSON_AUTHORITY.relative_path(),
+            parser: "JSON",
+            message: error.to_string(),
+        }
+    })?;
+    let packages = value
+        .get("workspaces")
+        .map(|field| {
+            field
+                .as_array()
+                .ok_or_else(|| PACKAGE_JSON_AUTHORITY.field_error("workspaces", "must be an array of strings"))?
+                .iter()
+                .map(|item| {
+                    item.as_str().map(ToOwned::to_owned).ok_or_else(|| {
+                        PACKAGE_JSON_AUTHORITY.field_error("workspaces", "must contain only strings")
+                    })
+                })
+                .collect::<Result<Vec<_>, _>>()
+        })
+        .transpose()?;
+    Ok(MembershipAuthority::Present(PackageJsonMembership {
+        packages,
+        hybrid_root: value.get("name").is_some(),
+    }))
+}
+
+fn read_pnpm_membership(root: &Path) -> Result<MembershipAuthority<Vec<String>>, LocateError> {
+    let Some(content) = read_authority(root, PNPM_AUTHORITY)? else {
+        return Ok(MembershipAuthority::Absent);
+    };
+    let documents = yaml_rust2::YamlLoader::load_from_str(&content).map_err(|error| {
+        LocateError::MembershipParse {
+            ecosystem: PNPM_AUTHORITY.ecosystem,
+            path: PNPM_AUTHORITY.relative_path(),
+            parser: "YAML",
+            message: error.to_string(),
+        }
+    })?;
+    let document = documents.first().ok_or_else(|| {
+        PNPM_AUTHORITY.field_error("document", "must contain one YAML mapping document")
+    })?;
+    if document.as_hash().is_none() {
+        return Err(PNPM_AUTHORITY.field_error("document", "must be a YAML mapping"));
+    }
+    let packages = match &document["packages"] {
+        yaml_rust2::Yaml::BadValue => Vec::new(),
+        yaml_rust2::Yaml::Array(items) => items
+            .iter()
+            .map(|item| {
+                item.as_str()
+                    .map(ToOwned::to_owned)
+                    .ok_or_else(|| PNPM_AUTHORITY.field_error("packages", "must contain only strings"))
+            })
+            .collect::<Result<Vec<_>, _>>()?,
+        _ => return Err(PNPM_AUTHORITY.field_error("packages", "must be an array of strings")),
+    };
+    Ok(MembershipAuthority::Present(packages))
+}
+
+pub(crate) fn read_npm_membership(root: &Path) -> Result<MembershipAuthority<NpmMembership>, LocateError> {
+    let pnpm = read_pnpm_membership(root)?;
+    let package_json = read_package_json_membership(root)?;
+    match pnpm {
+        MembershipAuthority::Present(packages) => {
+            let hybrid_root = matches!(&package_json, MembershipAuthority::Present(package) if package.hybrid_root);
+            Ok(MembershipAuthority::Present(NpmMembership {
+                globs: build_globset(&packages, PNPM_AUTHORITY, "packages")?,
+                hybrid_root,
+            }))
+        }
+        MembershipAuthority::Absent => match package_json {
+            MembershipAuthority::Absent => Ok(MembershipAuthority::Absent),
+            MembershipAuthority::Present(package) => match package.packages {
+                None => Ok(MembershipAuthority::Absent),
+                Some(packages) => Ok(MembershipAuthority::Present(NpmMembership {
+                    globs: build_globset(&packages, PACKAGE_JSON_AUTHORITY, "workspaces")?,
+                    hybrid_root: package.hybrid_root,
+                })),
+            },
+        },
+    }
+}
