+            std::fs::write(empty.path().join(file), format!("{table}\nmembers = []\n")).unwrap();
+            assert!(!admits(read_membership(empty.path(), spec).unwrap(), member_path, false), "{name} empty members");
+
+            let included = tempdir().unwrap();
+            std::fs::write(
+                included.path().join(file),
